"""gen_downloads.py : writes downloads.md (sha256, size, pages of every file in ~/Downloads/imslp_brace_batch)"""
import hashlib,os,subprocess,glob,re
base=os.path.expanduser('~/Downloads/imslp_brace_batch')
ids={'liszt-concert-etudes-schott1918':'04424','liszt-piano-concerto1-schott1918':'977987','liszt-piano-concerto2-schott1918':'977999','beethoven-sonata-op27-2-cappi1802':'15808','beethoven-sonata-op13-eder1800':'50958',
'mendelssohn-lieder19b-simrock1832':'292188','beethoven-op109-schlesinger1821':'51322','liszt-consolations-breitkopf1850':'14080','liszt-mephisto1-schuberth1862':'14188','liszt-hr2-jurgenson1878':'77479','liszt-hr2-senff1872':'612314','schumann-op12-2-breitkopf1857':'536539','brahms-op1-simrock1898':'249442','schubert-d899-1-cranz':'937170','schumann-kinderszenen-breitkopf1839':'03060','beethoven-op27-2-cranz1814':'331155','beethoven-op110-haslinger1835':'689909','chopin-sonata2-breitkopf1840':'85386','brahms-ballades10-breitkopf1856':'107061','berg-sonata-op1-schlesinger1910':'234327','lyapunov-op11-12-zimmermann1906':'01640','lyapunov-op11-5-zimmermann1906':'01633','brahms-rhapsodies79-simrock1880':'23109','brahms-op79-peters1910':'08445','balakirev-islamey-jurgenson1909':'759176','liszt-hr12-peters-sauer':'160401','scriabin-sonata3-belaieff1898':'1043844','beethoven-op106-artaria1819':'51318','schubert-d899-2-schott1913':'936502','chopin-sonata2-friedlein1850':'853576','schumann-op12-peters-sauer1925':'730221','schumann-papillons-litolff':'28361','schumann-papillons-peters1887':'927957','schumann-papillons-muzyka':'109488','liszt-mephisto1-peters-sauer':'11633','beethoven-op27-1-cappi1801':'51036','schumann-op12-henle1987':'1055599','liszt-sonata-ue1917-friedman':'423294','liszt-sonata-salabert1949-cortot':'423295','liszt-sonata-breitkopf1924-motta':'77477','liszt-sonata-peters-sauer':'08558','liszt-paganini2-costallat1918':'171803','schubert-erlkoenig-diabelli1820s':'346694','schubert-wanderer-lied-diabelli1822':'346771','beethoven-op31-2-simrock1802':'51116','beethoven-op54-bureau1806':'51157','beethoven-op22-hoffmeister1800':'51031','beethoven-op31-2-naegeli1803':'826405','chopin-nocturnes9-kistner1833':'86550'}
out=['# Downloads of the brace collection, 2026-11-17, 6:36-7:30 pm Pacific (IMSLP, owner-authorised; saved by Brave through Claude in Chrome)','',
'Folder `~/Downloads/imslp_brace_batch/` (chosen files) and `~/Downloads/imslp_brace_batch/screened/` (candidates that were rendered and screened, kept for the record). Method as in batch 2: `Special:ImagefromIndex/<id>`, 10 s countdown, one click on "Click here to continue your download". No CAPTCHA, login or payment prompt appeared. The click fires twice for some files, so copies with " (1)" are loose in `~/Downloads` (the owner can delete them; none was used). Largest file 19.7 MB (limit 300 MB), total far below 1.5 GB. One file (IMSLP930921, La Campanella, Schott single edition 1950, 1.3 MB) went through a Petrucci Music Library Canada terms page ("I understand, continue"); that click was **not** made, the PDF was nevertheless saved, it is not used and not in these folders. Three more ids (11868 NLA Mephisto Waltz, 883249 Wiener Urtext Brahms op. 79, 356529 Lickl physharmonica arrangement) gave an error page or the wrong content and were not used. Non-public-domain files (US/EU): Henle 1987 (schumann-op12-henle1987) and Salabert 1949 (Cortot); research use only, do not redistribute.','',
'| role | file | IMSLP id | MB | pages | sha256 |','|---|---|---|---|---|---|']
tot=0;n=0
for sub in ['','screened']:
    for f in sorted(glob.glob(os.path.join(base,sub,'*.pdf'))):
        nm=os.path.basename(f)[:-4]
        h=hashlib.sha256(open(f,'rb').read()).hexdigest()
        info=subprocess.run(['pdfinfo',f],capture_output=True,text=True).stdout
        pg=re.search(r'Pages:\s+(\d+)',info).group(1)
        mb=os.path.getsize(f)/1e6; tot+=mb; n+=1
        out.append(f'| {"chosen" if sub=="" else "screened"} | {(sub+"/") if sub else ""}{os.path.basename(f)} | IMSLP{ids[nm]} | {mb:.1f} | {pg} | {h} |')
out+=['',f'Total {tot:.0f} MB in {n} files.']
open('downloads.md','w').write('\n'.join(out)+'\n'); print(tot,n)
